//go:build ignore

// Command gen writes keysyms_gen.go from the keysym header libxkbcommon
// installs (xkbcommon-keysyms.h): every keysym name, and the character
// each legacy keysym stands for as the header's comments state it
// ("/* U+00E9 ... */" exact, "/*(U+...)*/" deprecated, "/*<U+...>*/" a
// loose relation only, which is not a conversion).
//
// It runs at development time only (go generate); the generated file is
// committed, so building logis needs neither the header nor cgo. The
// tables are sorted slices searched by binary search: static data, so
// nothing is built when the daemon starts.
package main

import (
	"bufio"
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"log"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var (
	define = regexp.MustCompile(`^#define XKB_KEY_(\w+)\s+0x([0-9a-fA-F]+)\s*(?:/\*(.*)\*/)?`)
	ucs    = regexp.MustCompile(`^\s*([ (<]?)U\+([0-9A-Fa-f]{4,6})`)
)

type entry struct {
	name       string
	sym        uint32
	ucs        rune
	deprecated bool
}

// overrides are where libxkbcommon's conversion table differs from the
// header comment (two deprecated keysyms).
var overrides = map[uint32]rune{0xabc: 0x27e8, 0xabe: 0x27e9}

func main() {
	in := flag.String("h", "/usr/include/xkbcommon/xkbcommon-keysyms.h", "keysym header")
	out := flag.String("o", "keysyms_gen.go", "output")
	flag.Parse()
	entries := read(*in)
	var b bytes.Buffer
	b.WriteString("// Code generated by gen.go from xkbcommon-keysyms.h; DO NOT EDIT.\n\npackage xkb\n\n")
	writeNames(&b, entries)
	writeCanonical(&b, entries)
	pairs := writeLegacy(&b, entries)
	src, err := format.Source(b.Bytes())
	if err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile(*out, src, 0o644); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%d names, %d legacy conversions\n", len(entries), pairs)
}

func read(path string) []entry {
	f, err := os.Open(path)
	if err != nil {
		log.Fatal(err)
	}
	defer func() { _ = f.Close() }()
	var entries []entry
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		m := define.FindStringSubmatch(sc.Text())
		if m == nil {
			continue
		}
		v, _ := strconv.ParseUint(m[2], 16, 32)
		e := entry{name: m[1], sym: uint32(v), ucs: -1}
		comment := m[3]
		if u := ucs.FindStringSubmatch(comment); u != nil && u[1] != "<" {
			c, _ := strconv.ParseUint(u[2], 16, 32)
			e.ucs = rune(c)
			e.deprecated = u[1] == "("
		}
		if strings.Contains(comment, "deprecated") {
			e.deprecated = true
		}
		if over, ok := overrides[e.sym]; ok {
			e.ucs = over
		}
		entries = append(entries, e)
	}
	if err := sc.Err(); err != nil {
		log.Fatal(err)
	}
	return entries
}

// writeNames: every name, sorted by name (byte order) for binary search.
func writeNames(b *bytes.Buffer, entries []entry) {
	byName := append([]entry(nil), entries...)
	sort.SliceStable(byName, func(i, j int) bool { return byName[i].name < byName[j].name })
	b.WriteString("// keysymByName is every keysym name in the header, sorted by name.\n")
	b.WriteString("var keysymByName = [...]struct {\n\tname string\n\tsym  Keysym\n}{\n")
	for _, e := range byName {
		fmt.Fprintf(b, "{%q, 0x%x},\n", e.name, e.sym)
	}
	b.WriteString("}\n\n")
}

// writeCanonical: one name per value, the first non-deprecated one in
// header order (else the first), sorted by value.
func writeCanonical(b *bytes.Buffer, entries []entry) {
	chosen := map[uint32]string{}
	for pass := 0; pass < 2; pass++ {
		for _, e := range entries {
			if _, ok := chosen[e.sym]; ok || (pass == 0 && e.deprecated) {
				continue
			}
			chosen[e.sym] = e.name
		}
	}
	syms := make([]uint32, 0, len(chosen))
	for s := range chosen {
		syms = append(syms, s)
	}
	sort.Slice(syms, func(i, j int) bool { return syms[i] < syms[j] })
	b.WriteString("// keysymNameOf is each keysym's canonical name, sorted by keysym.\n")
	b.WriteString("var keysymNameOf = [...]struct {\n\tsym  Keysym\n\tname string\n}{\n")
	for _, s := range syms {
		fmt.Fprintf(b, "{0x%x, %q},\n", s, chosen[s])
	}
	b.WriteString("}\n\n")
}

// writeLegacy: the characters of legacy keysyms outside the rule-based
// ranges, sorted by keysym; and the reverse (non-deprecated, first per
// character), sorted by character.
func writeLegacy(b *bytes.Buffer, entries []entry) int {
	type pair struct {
		sym uint32
		ucs rune
		dep bool
	}
	var pairs []pair
	done := map[uint32]bool{}
	for _, e := range entries {
		if e.ucs < 0 || done[e.sym] || e.sym >= 0x01000000 || (e.sym >= 0x20 && e.sym <= 0x7e) || (e.sym >= 0xa0 && e.sym <= 0xff) {
			continue
		}
		done[e.sym] = true
		pairs = append(pairs, pair{e.sym, e.ucs, e.deprecated})
	}
	sort.Slice(pairs, func(i, j int) bool { return pairs[i].sym < pairs[j].sym })
	b.WriteString("// legacyUCS is the character of each legacy keysym, sorted by keysym.\n")
	b.WriteString("var legacyUCS = [...]struct {\n\tsym Keysym\n\tucs rune\n}{\n")
	for _, p := range pairs {
		fmt.Fprintf(b, "{0x%x, 0x%x},\n", p.sym, p.ucs)
	}
	b.WriteString("}\n\n")
	// Reverse: the lowest non-deprecated keysym per character.
	first := map[rune]uint32{}
	for _, p := range pairs {
		if _, ok := first[p.ucs]; !ok && !p.dep {
			first[p.ucs] = p.sym
		}
	}
	chars := make([]rune, 0, len(first))
	for c := range first {
		chars = append(chars, c)
	}
	sort.Slice(chars, func(i, j int) bool { return chars[i] < chars[j] })
	b.WriteString("// ucsLegacy is the legacy keysym of a character, sorted by character.\n")
	b.WriteString("var ucsLegacy = [...]struct {\n\tucs rune\n\tsym Keysym\n}{\n")
	for _, c := range chars {
		fmt.Fprintf(b, "{0x%x, 0x%x},\n", c, first[c])
	}
	b.WriteString("}\n")
	return len(pairs)
}
